<!--
 * 快捷回复（列表页）
 *
 * @path apps\workflow-web\src\views\quick-comment\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 快捷回复（列表页）
 * <p>消费后端契约 FlowCommentController（src/api/flowComment.ts，auto-generated by bash/gen-contract.py）：
 * 常用意见列表 listQuickComments()（非分页，query 直接返回 { items, total: items.length }），
 * 支持新增、编辑、删除、使用（incrementUseCount 累计使用次数）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';
import { Page, useYDSZModal } from '@ydsz/common-ui';
import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h } from 'vue';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { deleteQuickComment, incrementUseCount, listQuickComments } from '#/api/flowComment';
import type { FlowQuickCommentVO } from '#/api/models';
import QuickCommentForm from './quick-comment-form.vue';
defineOptions({ name: 'QuickCommentManagement' });

/** 系统预置标识标签 */
function systemTag(isSystem: number | undefined) {
  return isSystem
    ? h(ElTag, { type: 'warning' }, () => '系统')
    : h(ElTag, { type: 'info' }, () => '个人');
}

const gridOptions: VxeGridProps<FlowQuickCommentVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'content', title: '评语内容', width: 320, showOverflow: 'title' },
    { field: 'commentType', title: '类型', width: 100 },
    { field: 'sortNum', title: '排序', width: 80 },
    { field: 'useCount', title: '使用次数', width: 90 },
    {
      field: 'isSystem',
      title: '来源',
      width: 90,
      slots: { default: ({ row }) => systemTag(row.isSystem) },
    },
    { field: 'updatedAt', title: '更新时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 170,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => '编辑',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleUse(row) },
              () => '使用',
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => '删除',
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      // listQuickComments() 为全量非分页接口：直接返回全部条目，total 取条目数
      query: async () => {
        const items = (await listQuickComments()) ?? [];
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [QuickCommentFormModal, quickCommentFormApi] = useYDSZModal({
  connectedComponent: QuickCommentForm,
});
function handleAdd() {
  quickCommentFormApi.open();
}
function handleEdit(row: FlowQuickCommentVO) {
  quickCommentFormApi.setData({ record: row });
  quickCommentFormApi.open();
}

/** 使用该常用意见（累计使用次数） */
async function handleUse(row: FlowQuickCommentVO) {
  if (!row.id) return;
  try {
    await incrementUseCount({ id: row.id });
    ElMessage.success('已使用');
    gridApi.query();
  } catch {
    // 请求失败提示由拦截器统一处理
  }
}

async function handleDelete(row: FlowQuickCommentVO) {
  if (!row.id) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(`确定删除「${row.content}」吗？`, '删除确认', { type: 'warning' });
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await deleteQuickComment({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="快捷评语">
      <template #toolbar-tools
        ><ElButton type="primary" @click="handleAdd">新增</ElButton></template
      >
    </Grid>
    <QuickCommentFormModal @success="gridApi.query()" />
  </Page>
</template>
